'use strict';
const $=id=>document.getElementById(id), copy=x=>JSON.parse(JSON.stringify(x));
const labels={time:'Tiempo',battery:'Batería',oxygen:'Oxígeno simulado',water:'Agua',nutrition:'Demanda energética'};
const states={SUCCESS:'Misión posible bajo el modelo',INFEASIBLE:'No se encontró una misión admisible',SEARCH_LIMIT_REACHED:'Cálculo interrumpido; factibilidad desconocida',INVALID_INPUT:'Revisa los datos introducidos'};
const policyNames={geometric_astar:'Recorrido rápido',balanced:'Equilibrada',minimum_time:'Tiempo mínimo',terrain_caution:'Cautela de terreno'};
const decisions={CONTINUE:'Continuar',RETURN:'Regresar',REVIEW_CONTINUATION_UNKNOWN:'Revisar: continuación desconocida',REVIEW_RETURN_UNCONFIRMED:'Revisar: regreso sin confirmar',REVIEW_INVALID_INPUT:'Revisa los datos introducidos'};
const phaseNames={outbound:'Ida',activity:'Actividad científica',inbound:'Regreso'};
const advancedLabels={agent_radius_m:'Radio (m)',safety_margin_m:'Margen geométrico (m)',max_slope_deg:'Pendiente máxima (°)',near_obstacle_m:'Proximidad (m)',slope_weight:'Peso de pendiente (adim.)',risk_weight:'Peso de riesgo (adim.)',roughness_weight:'Peso de rugosidad (adim.)',proximity_weight:'Peso de proximidad (adim.)',speed_m_per_min:'Velocidad (m/min)',uphill_speed_penalty:'Penalización de ascenso (adim.)',roughness_speed_penalty:'Penalización de rugosidad (adim.)',uphill_effort_penalty:'Penalización de esfuerzo (adim.)',climb_battery_wh_per_m:'Ascenso (Wh/m)',hazard_cost_weight:'Peso de terreno (adim.)',battery_cost_weight:'Peso de batería (min/Wh)'};
const fmt=n=>n===null||n===undefined?'—':typeof n==='number'?n.toLocaleString('es',{maximumFractionDigits:3}):String(n);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,config,map,points,routes,obstacles,regionOverlay,remoteLayer,regionalLayer,coverageBox,contextLayer,layerFailed=false;
let bundle=null,selected=0,revision=0,resultRevision=-1,busy=false,requestSeq=0,selectionSeq=0,mode='consult';
function status(text,kind=''){$('status').textContent=text;$('status').className=kind;}
function budgetInfo(){if(!config)return;$('budgetSummary').textContent='Saldos al calcular: '+fmt(config.remaining.time)+' min y '+fmt(config.remaining.battery)+' Wh. Reservas: '+fmt(config.profile.resources.time.reserve)+' min y '+fmt(config.profile.resources.battery.reserve)+' Wh. Editables en Recursos y reservas.';}
function saveInputs(){try{sessionStorage.setItem('mars-mission-inputs-v1',JSON.stringify({source:catalog.maps.regional.revision_sha256,configuration:config}));}catch{}}
function dirty(){saveInputs();budgetInfo();if(bundle){$('conditionsIntro').textContent='Condiciones del cálculo anterior; vuelve a calcular después de cambiar entradas.';}revision++;selectionSeq++;if(bundle)status('Resultados anteriores. Las entradas cambiaron; vuelve a calcular.','stale');else if(busy)status('Calculando entradas anteriores. La configuración actual requiere otro cálculo.','stale');draw();}
function cellData(cell){return cell?catalog.maps.regional.cells.find(x=>x.cell[0]===cell[0]&&x.cell[1]===cell[1]):null;}
function entries(){const r=bundle?.result;return !r?[]:r.alternatives||[r.continuation,r.returning];}
function setMode(value){mode=value;selectionSeq++;$('selectionInfo').textContent={base:'Haz clic dentro del área habilitada para fijar la salida.',goal:'Haz clic dentro del área habilitada para fijar el destino.',current:'Haz clic para indicar la posición actual manual.',obstacle:'Haz clic para alternar un obstáculo SIMULADO; el CTX original no cambia.',consult:'Haz clic para consultar coordenadas y elevación.'}[value];}
function numeric(label,value,fn,readonly=false){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.type='number';i.step='any';i.value=value;i.readOnly=readonly;i.oninput=()=>{fn(i.value===''?null:Number(i.value));dirty();};l.append(i);return l;}
function controls(){
  $('agent').value=config.agent;$('missionMode').value=config.mission_mode;$('activityStatus').value=config.activity_status;$('activity').value=config.activity_min;$('activity').disabled=config.activity_status==='completed';$('scenario').value=config.scenario;$('factor').value=config.factor;$('factor').disabled=config.scenario==='nominal';$('limit').value=config.max_labels;
  $('currentPanel').hidden=config.mission_mode==='new';$('evaluate').hidden=config.mission_mode==='new';$('personal').hidden=config.agent!=='astronaut';$('mass').value=config.personal.body_mass_kg??'';$('height').value=config.personal.height_m??'';
  $('planningMethod').value=config.planning_method||'fast';budgetInfo();
  $('profileInfo').textContent=config.profile.profile_id+' · v'+config.profile.version+' · SIMULADO, sin calibración física.';
  $('resourceInputs').replaceChildren();
  for(const [key,r] of Object.entries(config.profile.resources)){
    const box=document.createElement('div');box.className='resourceInput';const title=document.createElement('h3');title.textContent=labels[key]+' ('+r.unit+')';box.append(title);
    if(r.status==='not_applicable'){box.append('No aplica');$('resourceInputs').append(box);continue;}
    if(!['time','battery'].includes(key)){
      const l=document.createElement('label');l.textContent='Tratamiento experimental';const s=document.createElement('select');s.innerHTML='<option value="modeled">Modelado</option><option value="excluded">Exclusión explícita</option>';s.value=r.status;s.onchange=()=>{if(s.value==='excluded'){config.profile.resources[key]={status:'excluded',unit:r.unit,reason:'Exclusión experimental declarada'};delete config.remaining[key];}else{const v=copy(catalog.defaults.regional[config.agent].profile.resources[key]);config.profile.resources[key]=v;config.remaining[key]=v.capacity;}dirty();controls();};l.append(s);box.append(l);
    }
    if(r.status==='excluded'){const l=document.createElement('label');l.textContent='Motivo de exclusión (obligatorio)';const i=document.createElement('input');i.value=r.reason;i.oninput=()=>{r.reason=i.value;dirty();};l.append(i);box.append(l);}
    else{const f=document.createElement('div');f.className='fields';f.append(numeric('Capacidad original ('+r.unit+')',r.capacity,v=>r.capacity=v),numeric('Saldo al calcular ('+r.unit+')',config.remaining[key],v=>config.remaining[key]=v),numeric('Reserva absoluta ('+r.unit+')',r.reserve,v=>r.reserve=v),numeric('Tasa movimiento ('+r.unit+'/min)',r.movement_rate,v=>r.movement_rate=v,key==='time'),numeric('Tasa actividad ('+r.unit+'/min)',r.activity_rate,v=>r.activity_rate=v,key==='time'));box.append(f);}
    $('resourceInputs').append(box);
  }
  $('advanced').replaceChildren();for(const group of ['mobility','motion']){const f=document.createElement('div');f.className='fields';for(const [k,v]of Object.entries(config.profile[group]))f.append(numeric(advancedLabels[k],v,n=>config.profile[group][k]=n));$('advanced').append(f);}
  pointInfo();draw();
}
function pointInfo(){for(const key of ['base','goal','current']){const data=cellData(config[key]),picked=config.selections?.[key];$(key+'Info').textContent=data?`${picked?'Punto elegido · ajuste '+fmt(picked.adjustment_m)+' m':'Punto de ejemplo · puedes cambiarlo'}`:'Sin punto; márcalo en el mapa.';}$('perturbation').textContent=config.obstacles.length+' obstáculos simulados. Ninguno representa una observación científica.';}
function marsCRS(){return L.extend({},L.CRS,{projection:L.Projection.LonLat,transformation:new L.Transformation(1/180,1,-1/180,.5),scale:z=>256*2**z,zoom:s=>Math.log2(s/256),infinite:false,wrapLng:[-180,180],distance:(a,b)=>{const d=Math.PI/180,p=a.lat*d,q=b.lat*d;return 2*3396190*Math.asin(Math.min(1,Math.sqrt(Math.sin((q-p)/2)**2+Math.cos(p)*Math.cos(q)*Math.sin((b.lng-a.lng)*d/2)**2)));}});}
function initMap(){
  $('layerMeta').open=false;
  map=L.map('missionMap',{crs:marsCRS(),minZoom:6,maxZoom:18,zoomSnap:.5,maxBounds:[[17.8,76.7],[19.15,78.3]],maxBoundsViscosity:.8,attributionControl:false});
  points=L.layerGroup().addTo(map);routes=L.layerGroup().addTo(map);obstacles=L.layerGroup().addTo(map);
  coverageBox=L.rectangle(catalog.maps.regional.bounds,{color:'#8af0c7',weight:2,fillOpacity:.04,dashArray:'7 5'}).addTo(map).bindTooltip('Área habilitada · 2 × 2 km',{sticky:true});
  coverageBox.on('click',e=>selectPoint(e.latlng));map.on('click',e=>selectPoint(e.latlng));
  // Coverage rectangle click bubbles through Leaflet; only map dispatch handles selection.
  coverageBox.off('click');
  map.on('moveend zoomend',viewInfo);map.fitBounds(catalog.maps.regional.bounds,{padding:[45,45],animate:false});setLayer();
}
function setLayer(){
  if(remoteLayer)map.removeLayer(remoteLayer);if(regionalLayer)map.removeLayer(regionalLayer);if(contextLayer)map.removeLayer(contextLayer);layerFailed=false;$('layerError').textContent='';
  const kind=$('layer').value,source=catalog.cartography.layers[kind==='orbital'?'orbital':'relief'];
  if(!$('localOnly').checked){
  if(kind==='orbital'){const context=catalog.cartography.layers.relief;contextLayer=L.tileLayer(`https://trek.nasa.gov/tiles/Mars/EQ/${context.product}/1.0.0/default/default028mm/{z}/{y}/{x}.jpg`,{maxZoom:18,maxNativeZoom:8,noWrap:true,bounds:context.bounds,keepBuffer:1,zIndex:0}).addTo(map);contextLayer.on('tileerror',()=>{layerFailed=true;$('layerError').textContent='No se pudo cargar el relieve remoto de contexto. Revisa la conexión; las capas CTX locales siguen disponibles.';});}
  const url=`https://trek.nasa.gov/tiles/Mars/EQ/${source.product}/1.0.0/default/default028mm/{z}/{y}/{x}.${source.extension}`;
  remoteLayer=L.tileLayer(url,{minZoom:0,maxZoom:18,maxNativeZoom:source.max_zoom,noWrap:true,bounds:source.bounds,keepBuffer:1});
  remoteLayer.on('tileerror',()=>{layerFailed=true;$('layerError').textContent='No se pudo cargar parte de la capa remota (red o cobertura). Relieve y elevación CTX locales siguen disponibles.';});remoteLayer.addTo(map);
  }else{remoteLayer=null;contextLayer=null;layerFailed=true;$('layerError').textContent=kind==='orbital'?'Imagen orbital no disponible en modo local. Selecciona Relieve o Elevación para ver el CTX guardado.':'Solo datos locales: fuera del área CTX no hay capa cargada. Las solicitudes de teselas remotas están desactivadas.';}
  if(kind!=='orbital')regionalLayer=L.imageOverlay('/regional-'+(kind==='elevation'?'elevation':'relief')+'.png',catalog.maps.regional.bounds,{opacity:.95,interactive:false,className:'demRaster'}).addTo(map);
  $('layerInfo').textContent=kind==='orbital'?`${source.source}. ${source.type}; ${source.resolution}. Cobertura parcial de Jezero sobre relieve de contexto MOLA/HRSC (200 m/píxel). Por encima del zoom nativo solo se amplía la imagen.`:`${source.source}. Contexto sombreado de 200 m/píxel; dentro del área, ${kind==='elevation'?'elevación coloreada':'sombreado calculado NW, 45°'} de CTX local de 20 m.`;
  if($('localOnly').checked)$('layerInfo').textContent=kind==='orbital'?'MRO CTX orbital: servicio remoto no cargado. Sin sustitución por imágenes inventadas.':'CTX local: 20 m de resolución; '+(kind==='elevation'?'elevación con color añadido.':'sombreado calculado NW, 45°.');
  const heights=catalog.maps.regional.cells.map(x=>x.height_m).filter(x=>x!==null);$('legend').textContent=kind==='elevation'?`Elevación absoluta CTX (color añadido): azul ${fmt(Math.min(...heights))} m → ocre ${fmt(Math.max(...heights))} m`:'Área verde: cobertura de cálculo · Trazo turquesa: ida · Naranja discontinuo: regreso';viewInfo();
}
function viewInfo(){if(!map)return;const c=map.getCenter(),b=map.getBounds();const width=map.getSize().x,distance=map.distance(L.latLng(c.lat,b.getWest()),L.latLng(c.lat,b.getEast()));const meters=distance/width*120;$('scale').textContent=meters>=1000?fmt(meters/1000)+' km':fmt(meters)+' m';const inside=L.latLngBounds(catalog.maps.regional.bounds).contains(c);$('mapHint').textContent=inside?'Área de cálculo: 2 × 2 km · Resolución 20 m. Marca los centros usados por el motor.':'Exploración cartográfica. Pulsa «Área de cálculo» para planificar con el DEM local.';
  if(!$('localOnly').checked&&$('layer').value==='orbital'&&!L.latLngBounds(catalog.cartography.layers.orbital.bounds).contains(c))$('layerError').textContent='Fuera de la imagen CTX: aquí se muestra solo relieve de contexto MOLA/HRSC, sin cobertura de cálculo.';else if(!layerFailed)$('layerError').textContent='';
}
async function post(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const value=await r.json();if(!r.ok)throw Object.assign(new Error(value.message),{payload:value});return value;}
async function selectPoint(latlng){
  const point=[latlng.lat,latlng.lng],token=++selectionSeq,rev=revision;
  $('coordinateInfo').textContent=`Elegido: ${point[0].toFixed(7)}° N, ${point[1].toFixed(7)}° E`;
  try{const data=await post('/api/select',{configuration:copy(config),point});if(token!==selectionSeq||rev!==revision)return;
    $('coordinateInfo').textContent+=` · CTX ${fmt(data.height_m)} m · Ajuste ${fmt(data.adjustment_m)} m`;
    if(mode==='consult'){$('selectionInfo').textContent=`Elevación CTX ${fmt(data.height_m)} m. Centro usado: ${data.used_latlon.map(x=>x.toFixed(7)).join(', ')}°. `+data.message;return;}
    if(mode==='obstacle'){const i=config.obstacles.findIndex(x=>x.toString()===data.cell.toString());if(i<0)config.obstacles.push(data.cell);else config.obstacles.splice(i,1);dirty();pointInfo();return;}
    if(!data.traversable){$('selectionInfo').textContent=data.message+' El punto no se ha cambiado.';return;}
    config[mode]=data.cell;config.selections[mode]=data;if(mode==='base'&&config.mission_mode==='new'){config.current=data.cell.slice();config.selections.current=copy(data);}dirty();pointInfo();draw();$('selectionInfo').textContent=`Punto elegido ${point.map(x=>x.toFixed(7)).join(', ')}°. Centro utilizado ${data.used_latlon.map(x=>x.toFixed(7)).join(', ')}°; ajuste ${fmt(data.adjustment_m)} m.`;
  }catch(e){if(token===selectionSeq)$('selectionInfo').textContent=e.message;}
}
function draw(){if(!map||!config)return;points.clearLayers();routes.clearLayers();obstacles.clearLayers();
  for(const [key,label,color]of [['base','Salida / base','#90f4d3'],['goal','Destino / actividad','#ffbf80'],['current','Posición actual','#e3edf3']]){if(key==='current'&&config.mission_mode==='new')continue;const data=cellData(config[key]);if(!data)continue;L.circleMarker(data.latlon,{radius:7,color:'#172f35',weight:2,fillColor:color,fillOpacity:1}).addTo(points).bindTooltip(label,{permanent:true,direction:key==='base'?'left':'right'});const p=config.selections?.[key];if(p&&p.adjustment_m>.01){L.circleMarker(p.chosen_latlon,{radius:3,color:'#fff',weight:1,fillOpacity:1}).addTo(points).bindTooltip('Punto elegido; centro de cálculo a '+fmt(p.adjustment_m)+' m');L.polyline([p.chosen_latlon,data.latlon],{color:'#ddd',dashArray:'2 3',weight:1}).addTo(points);}}
  for(const cell of config.obstacles){const d=cellData(cell);if(d){const box=catalog.maps.regional.bounds,dy=(box[1][0]-box[0][0])/catalog.maps.regional.rows/2,dx=(box[1][1]-box[0][1])/catalog.maps.regional.columns/2;L.rectangle([[d.latlon[0]-dy,d.latlon[1]-dx],[d.latlon[0]+dy,d.latlon[1]+dx]],{color:'#c13930',weight:2,fillOpacity:.35}).addTo(obstacles).bindTooltip('Obstáculo SIMULADO · celda de 20 m');}}
  if(resultRevision!==revision)return;const a=entries()[selected];if(!a?.plan)return;const p=a.plan,g=p.goal_index,paths={outbound:g===null?[]:p.path.slice(0,g+1),inbound:g===null?p.path:p.path.slice(g)};
  for(const [phase,cells]of Object.entries(paths)){if($('phase').value!=='both'&&$('phase').value!==phase)continue;if(!cells.length)continue;L.polyline(cells.map(c=>cellData(c).latlon),{color:phase==='outbound'?'#59f1d8':'#ffb471',weight:phase==='outbound'?5:3,lineCap:'round',lineJoin:'round',dashArray:phase==='inbound'?'9 7':null}).addTo(routes).bindTooltip(phaseNames[phase]);}
}
async function calculate(action='compare'){
  if(busy)return;if(!config.base||!config.goal||!config.current){status('Marca la salida, el destino y, si corresponde, la posición actual.','error');return;}
  busy=true;const token=++requestSeq,start=revision,sent=copy(config);$('calculate').disabled=$('evaluate').disabled=true;status('Calculando con el motor Python… Los resultados visibles son anteriores.');
  try{const value=await post('/api/calculate',{configuration:sent,action});if(token!==requestSeq)return;bundle=value;selected=0;resultRevision=start;renderResults();if(start!==revision)status('Resultados anteriores: cambiaste entradas durante el cálculo. Vuelve a calcular.','stale');else{const a=entries(),codes=[...new Set(a.map(x=>x.status))];status(a.every(x=>x.status==='INFEASIBLE')&&a[0].ui_diagnostic?a[0].ui_diagnostic.summary:codes.map(c=>states[c]).join(' · '));}draw();}
  catch(e){if(token===requestSeq){bundle={configuration:sent,error:e.payload||{message:e.message}};resultRevision=-1;$('alternatives').replaceChildren();$('resultDetail').replaceChildren();$('conditionValues').replaceChildren();$('conditionsIntro').textContent='Corrige los datos para evaluar las condiciones de la misión.';$('recommendation').textContent='';$('coincidence').textContent='';$('diagnosticActions').hidden=true;status((e.payload?.status==='INVALID_INPUT'?'Revisa los datos introducidos. ':'Error de cálculo. ')+e.message,'error');enableExports();draw();}}
  finally{if(token===requestSeq){busy=false;$('calculate').disabled=$('evaluate').disabled=false;}}
}
function enableExports(){for(const k of ['exportConfig','exportResult','exportWaypoints'])$(k).disabled=!bundle;}
function renderResults(){const r=bundle.result,list=entries();$('alternatives').hidden=bundle.planning_method==='geometric_astar';enableExports();$('diagnosticActions').hidden=!list.some(x=>x.status!=='SUCCESS');$('reviewObstacles').hidden=$('clearAndRecalculate').hidden=!config.obstacles.length;$('reviewObstacles').textContent='Ver obstáculos simulados ('+config.obstacles.length+')';$('recommendation').textContent=r.decision?`${decisions[r.decision]}. ${r.message}`:`Ruta recomendada según el perfil, los recursos y el criterio configurado: ${r.recommendation?policyNames[r.recommendation]:'ninguna alternativa satisfactoria'}. Entre las satisfactorias se elige menor tiempo, luego batería y finalmente Equilibrada → Tiempo mínimo → Cautela de terreno.`;
  $('coincidence').textContent=r.coincident_routes?`${r.distinct_successful_routes} ${r.distinct_successful_routes===1?'ruta distinta: las políticas coinciden.':'rutas distintas calculadas.'} Grupos: ${r.coincident_routes.map(g=>g.map(k=>policyNames[k]).join(' + ')).join(' / ')||'ninguno'}`:'Cada opción conserva su estado; un regreso sin confirmar no queda garantizado.';
  $('alternatives').innerHTML=list.map((a,i)=>`<button class="alt ${i===selected?'selected':''}" data-alt="${i}"><strong>${r.decision?(a.mode==='continue'?'Continuar vía destino':'Regreso directo'):policyNames[a.policy]}</strong><span class="${a.status}">${states[a.status]}</span><span>${a.plan?fmt(a.plan.total.distance_m)+' m · '+fmt(a.plan.total.duration_min)+' min · '+fmt(a.plan.total.resources.battery.consumed)+' Wh':'Sin ruta confirmada'}</span></button>`).join('');
  if(bundle.planning_method==='geometric_astar'){$('recommendation').textContent='Modo rápido: busca un recorrido transitable y después calcula los recursos completos. No necesitas modificar límites de búsqueda.';$('coincidence').textContent='Un recorrido A* calculado; no se comparan tres políticas en este modo.';}document.querySelectorAll('[data-alt]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.alt);renderResults();draw();});detail(list[selected]);$('trace').textContent=`Cálculo ${bundle.calculation_id} · ${bundle.created_utc}. Las descargas pertenecen a estas entradas aunque edites la misión.`;$('technical').textContent=JSON.stringify({terrain:bundle.terrain,input_sha256:bundle.input_sha256,rule:r.rule},null,2);
}
function detail(a){const c=a.mission_conditions;$('adjustResources').hidden=!c?.resources?.some(r=>r.required_initial>r.current_initial+1e-9);$('adjustResources').textContent=c?.kind==='OPTIMISTIC_MINIMUM'?'Buscar recorrido y calcular recursos':'Preparar recursos para este recorrido';$('adjustmentNote').textContent=c?.kind==='OPTIMISTIC_MINIMUM'?'El ajuste aplica mínimos optimistas, incluidas las reservas. No garantiza encontrar una ruta; pendientes y desvíos pueden exigir más.':'';$('conditionsIntro').textContent=c?c.message:'La misión necesita puntos transitables, recursos de ida y regreso y reservas al terminar. Revisa el diagnóstico para saber qué impide este cálculo.';$('conditionValues').innerHTML=c?'<table><thead><tr><th>Recurso</th><th>Necesitas</th><th>Tienes</th></tr></thead><tbody>'+c.resources.map(r=>'<tr class="'+(r.satisfied?'SUCCESS':'INFEASIBLE')+'"><td>'+labels[r.resource]+'</td><td>'+fmt(r.required_initial)+' '+r.unit+'</td><td>'+fmt(r.current_initial)+' '+r.unit+'</td></tr>').join('')+'</tbody></table>':'';const d=a.ui_diagnostic;let html=`<h3>${policyNames[a.policy]}</h3>`;if(d){html+='<div class="missionDiagnosis"><strong>'+esc(d.summary)+'</strong><p>'+esc(d.next_step)+'</p>';if(d.resources?.length){html+='<p>Distancia futura mínima: '+fmt(d.minimum_future_distance_m)+' m (ida y regreso en una misión nueva).</p>';for(const r of d.resources)html+='<p><strong>'+esc(r.name)+'</strong>: como mínimo '+fmt(r.minimum_consumption)+' '+r.unit+' de consumo; saldo utilizable sobre reserva '+fmt(r.available_above_reserve)+' '+r.unit+'. Faltan al menos '+fmt(r.minimum_shortfall)+' '+r.unit+'.</p>';html+='<p class="help">'+esc(d.scope)+'</p>';}html+='</div>';}else html+=`<p class="help">${esc(a.message)}</p>`;
  if(a.plan){html+='<details><summary>Detalle de recursos (opcional)</summary>';for(const [k,v]of Object.entries(a.plan.total.resources)){html+=`<div class="resourceSummary"><strong>${labels[k]} (${v.unit})</strong>`;html+=v.status==='modeled'?'<dl>'+[['Saldo inicial del cálculo','capacity'],['Consumo futuro','consumed'],['Restante al regresar','remaining'],['Reserva absoluta','reserve'],['Margen sobre reserva','margin_above_reserve']].map(([label,key])=>`<dt>${label}</dt><dd>${fmt(v[key])}</dd>`).join('')+'</dl>':v.status==='excluded'?'Exclusión experimental: '+esc(v.reason):'No aplica';html+='</div>';}
    html+='</details><details><summary>Ida, actividad, regreso y eventos</summary>';for(const k of ['outbound','activity','inbound']){const v=a.plan.phases[k];html+=`<div class="phaseEntry"><strong>${phaseNames[k]}</strong> · ${fmt(v.duration_min)} min · ${fmt(v.distance_m)} m<p>${Object.entries(v.consumed).map(([key,n])=>labels[key]+': '+fmt(n)+' '+a.plan.total.resources[key].unit).join(' · ')}</p></div>`;}for(const e of a.plan.events)html+=`<div class="phaseEntry">${e.index+1}. ${phaseNames[e.phase]} · ${fmt(e.duration_min)} min<p>${Object.entries(e.incremental).map(([key,n])=>labels[key]+': '+fmt(n)).join(' · ')}</p></div>`;html+='</details>';}
  html+='<details><summary>Códigos, criterio y perfil efectivo</summary><pre>'+esc(JSON.stringify({status:a.status,reason:a.reason_code,policy:a.policy,message:a.message,diagnostic:a.ui_diagnostic,metrics:a.search_metrics,weights:a.policy_weights,original_profile:a.request?.profile,effective_profile:a.effective_profile},null,2))+'</pre></details>';$('resultDetail').innerHTML=html;
}
function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function resetProfile(){const base=config?.base,goal=config?.goal,current=config?.current,missionMode=config?.mission_mode,selection=config?.selections;const method=config?.planning_method||'fast';config=copy(catalog.defaults.regional[$('agent').value]);config.planning_method=method;if(base){config.base=base;config.goal=goal;config.current=current;config.mission_mode=missionMode;config.selections=selection;}dirty();controls();}
$('setBase').onclick=()=>setMode('base');$('setGoal').onclick=()=>setMode('goal');$('setCurrent').onclick=()=>setMode('current');$('consult').onclick=()=>setMode('consult');$('obstacle').onclick=()=>setMode('obstacle');
for(const k of ['base','goal'])$('clear'+(k==='base'?'Base':'Goal')).onclick=()=>{config[k]=null;delete config.selections[k];if(k==='base'&&config.mission_mode==='new')config.current=null;dirty();pointInfo();};
$('planningMethod').onchange=()=>{config.planning_method=$('planningMethod').value;dirty();};$('agent').onchange=resetProfile;$('resetProfile').onclick=resetProfile;$('missionMode').onchange=()=>{config.mission_mode=$('missionMode').value;if(config.mission_mode==='new'){config.current=config.base?.slice()||null;config.selections.current=copy(config.selections.base||null);}dirty();controls();setMode('consult');};
$('activityStatus').onchange=()=>{config.activity_status=$('activityStatus').value;if(config.activity_status==='completed')config.activity_min=0;dirty();controls();};
for(const [id,key]of [['activity','activity_min'],['factor','factor'],['limit','max_labels']])$(id).oninput=()=>{config[key]=$(id).value===''?null:Number($(id).value);dirty();};
$('scenario').onchange=()=>{config.scenario=$('scenario').value;dirty();controls();};for(const [id,key]of [['mass','body_mass_kg'],['height','height_m']])$(id).oninput=()=>{config.personal[key]=$(id).value===''?null:Number($(id).value);dirty();};
$('adjustResources').onclick=()=>{const a=entries()[selected],c=a?.mission_conditions;if(!c||resultRevision!==revision){status('Vuelve a calcular antes de ajustar recursos.','stale');return;}if(c.kind==='OPTIMISTIC_MINIMUM'){config.planning_method='fast';dirty();controls();calculate('compare');return;}const changes=[];for(const r of c.resources){const old=config.remaining[r.resource],value=Math.max(old,r.required_initial);if(value>old){config.remaining[r.resource]=value;config.profile.resources[r.resource].capacity=Math.max(config.profile.resources[r.resource].capacity,value);changes.push({resource:r.resource,previous:old,adjusted:value});}}config.resource_adjustments=[...(config.resource_adjustments||[]),{basis:c.kind,calculation_id:bundle.calculation_id,changes,reserves_unchanged:true}];dirty();controls();calculate('compare');};
$('reviewResources').onclick=()=>{$('resourcesPanel').open=true;$('resourcesPanel').scrollIntoView({block:'start'});};$('reviewObstacles').onclick=()=>{$('obstacle').closest('details').open=true;setMode('obstacle');map.fitBounds(catalog.maps.regional.bounds,{padding:[45,45],animate:false});$('missionMap').scrollIntoView({block:'start'});};$('clearAndRecalculate').onclick=()=>{config.obstacles=[];dirty();pointInfo();setMode('consult');calculate('compare');};
$('restore').onclick=()=>{config.obstacles=[];dirty();pointInfo();};$('phase').onchange=draw;$('calculate').onclick=()=>calculate('compare');$('evaluate').onclick=()=>calculate('evaluate');$('layer').onchange=setLayer;$('localOnly').onchange=setLayer;
$('overview').onclick=()=>map.fitBounds(catalog.cartography.overview_bounds,{animate:false});$('coverage').onclick=()=>map.fitBounds(catalog.maps.regional.bounds,{padding:[45,45],animate:false});$('fitRoute').onclick=()=>{const p=entries()[selected]?.plan;if(p&&resultRevision===revision)map.fitBounds(L.latLngBounds(p.path.map(c=>cellData(c).latlon)),{padding:[70,70],maxZoom:17,animate:false});else status('Calcula una ruta actual antes de ajustar la vista.',bundle?'stale':'');};
$('exportConfig').onclick=()=>download({configuration:bundle.configuration,request:bundle.request,terrain:bundle.terrain,provenance:bundle.provenance},'mission-configuration.json');$('exportResult').onclick=()=>download(bundle,'mission-result.json');$('exportWaypoints').onclick=()=>download({calculation_id:bundle.calculation_id,terrain:bundle.terrain,frames:bundle.frames,units:bundle.units,provenance:bundle.provenance,perturbations:bundle.perturbations,waypoints:bundle.waypoints||[]},'mission-waypoints.json');
fetch('/api/catalog').then(r=>{if(!r.ok)throw new Error('No se pudo cargar el catálogo local');return r.json();}).then(data=>{catalog=data;config=copy(catalog.defaults.regional.astronaut);config.planning_method='fast';try{const saved=JSON.parse(sessionStorage.getItem('mars-mission-inputs-v1')||'null');if(saved?.source===catalog.maps.regional.revision_sha256&&['astronaut','rover'].includes(saved.configuration?.agent))config=saved.configuration;}catch{}$('provenance').textContent=JSON.stringify(catalog.maps.regional.provenance,null,2);initMap();controls();}).catch(e=>status(e.message,'error'));
